/// @brief Copies C-style command-line arguments into a std::vector<std::string>.
///
/// Centralises the pointer arithmetic required to iterate a raw argv array so
/// that call sites do not need to suppress cppcoreguidelines-pro-bounds-pointer-arithmetic.
/// Caller is responsible for validating @p argv is non-null before invocation.
///
/// @param argc   Number of elements in @p argv.
/// @param argv   Pointer to an array of @p argc C-strings.
/// @param offset Optional number of leading elements to skip (e.g. 1 to drop the program name).
/// @return A std::vector<std::string> containing argv[offset..argc).
///
inline std::vector<std::string>
argvToVector(const std::size_t argc, const char* const* const argv, const std::size_t offset = 0U)
{
   // Caller-verified: offset <= argc
   // NOLINTNEXTLINE(cppcoreguidelines-pro-bounds-pointer-arithmetic)
   return std::vector<std::string>{argv + offset, argv + argc};
}

