/// @brief Checks whether a time difference is within a valid range.
///
/// This function determines whether the difference between a reference time and a target time
/// is within a specified half-validity timespan, with a small epsilon margin for comparison
/// accuracy.
///
/// @param timeDifferenceSeconds The pre-computed time difference in seconds
///                              (e.g. `(referenceTime - targetTime).value`).
/// @param timespanHalfValidity The half-validity timespan (in seconds)
///                             that defines the valid range around the reference time.
/// @return true if the absolute time difference is less than the half-validity timespan
///         (plus a small epsilon). Otherwise, false.
inline bool isTimeValid(const double timeDifferenceSeconds, const double timespanHalfValidity)
{
   return std::fabs(timeDifferenceSeconds) < (timespanHalfValidity + TIME_COMPARISON_EPSILON);
